  function monsterLoot(e, win, info) {
    const meta = MONSTER_V2[e.s]; if (!meta || e.boss) return '';
    const r = gameState.monsterStats[e.n], drops = [];
    if (win) {
      if (!r.normalLoot) { r.normalLoot = true; drops.push(meta.loot); }
      else if (!r.rareLoot && Math.random() < rareLootRate()) { r.rareLoot = true; drops.push('稀有・' + meta.loot); }
      if (info.challenge) r.star3 = true;
    }
    return '<br>🔥 ×' + Math.min(5, gameState.encounter.battleStreak) + '　👮 ' + '■'.repeat(gameState.player.suspicion) + '□'.repeat(5 - gameState.player.suspicion) + (drops.length ? '<br>🎒 獲得：' + drops.map(esc).join('、') : '') + (win && info.challenge ? '<br>⭐ 特殊挑戰完成' : '');
  }
